function classifyLines(invoice, lineIds) {
  for (const id of lineIds) {
    const line = invoice.lines[id];
    if (line.classification !== '') continue;
    line.classification = matchRules(line);
  }
}
function importInvoice(invoice, request) {
  classifyLines(invoice, request.lineIds);
  saveInvoice(invoice);
}
function submitPortalInvoice(invoice) {
  classifyLines(invoice, Object.keys(invoice.lines));
  saveInvoice(invoice);
}

