function webhook(invoice, payload) {
  if (!Array.isArray(payload.lineIds) || payload.lineIds.some(id => !Object.hasOwn(invoice.lines, id))) {
    return response(400);
  }
  classifyLines(invoice, payload.lineIds);
  saveInvoice(invoice);
  return response(200);
}

